// Test block Toasts (Feedback): Short messages that confirm something just happened, bottom right on the desktop and bottom centre on the phone, gone after a few seconds.
//
// Generated by tools/blocks_from_app_blocks.py from the App Block card kit/blocks/feedback/Toasts.md and its markup
// (kit/blocks/feedback/Toasts.html, kit/blocks/feedback/Toasts.2.html; source b0bc6db6321a), with the vocabulary in
// functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.
//
// Steps (e2e):
//   Then I see the toast {text}
//   Then I see no toast
//   Then I see {n} toasts
//   When I press {name} on the toast
//   Then the toaster is in the {state} state
// States (from the card): Success, Info, Warning, Error, With an action, Hover or focus, Several, Closing,
// Invitation sent. Checked by the state step: Success, Error.
import { Registry } from '../../js/registry.js';
import * as p from '../../js/primitives.js';

export const BLOCK = 'Toasts';
export const ROUTE = '';
export const STATES = ["Success", "Info", "Warning", "Error", "With an action", "Hover or focus", "Several", "Closing", "Invitation sent"];
export const DEFAULT_STATE = 'Success';
export const CHECKED_STATES = ["Success", "Error"];
export const DEMO = ["kit/blocks/feedback/Toasts.2.html"];
export const SELF_TEST = [
  "Then I see the toast \"Note deleted\"",
  "Then I see 1 toasts",
  "Then the toaster is in the \"Success\" state",
  "When I press \"Undo\" on the toast",
];

export const steps = new Registry({ block: BLOCK });

/** The Toasts block on a page: its controls, found as a person finds them (role and name, label, text). */
export class Toasts {
  constructor(page, baseURL = '') {
    this.page = page;
    this.baseURL = baseURL;
  }

  async toaster() {
    return p.control(this.page, { css: '#toaster', block: BLOCK });
  }

  async toasts() {
    return p.control(await this.toaster(), { css: '.toast', block: BLOCK });
  }

  /** Every match, possibly none (for counting). */
  async toastsAll() {
    return (await this.toaster()).locator('.toast');
  }

  async toast(text) {
    return (await p.control(await this.toaster(), { css: '.toast', block: BLOCK })).filter({ hasText: String(text) });
  }

  async action(name) {
    return p.control(await this.toaster(), { role: 'button', name: String(name), block: BLOCK });
  }

  async success() {
    return p.control(await this.toaster(), { css: '.toast[data-category="success"]', block: BLOCK });
  }

  async error() {
    return p.control(await this.toaster(), { css: '.toast[data-category="error"]', block: BLOCK });
  }

  /** Check one of the card's states: Success, Error. */
  async expectState(state) {
    const b = this;
    if (state === 'Success') {
      await p.expectVisible((await b.success()).first());
    } else if (state === 'Error') {
      await p.expectVisible((await b.error()).first());
    } else {
      throw new Error(`Toasts has no check for the state '${state}'; checked: ${CHECKED_STATES.join(', ')}`);
    }
  }
}

steps.step("Then I see the toast {text}", async (world, { text }) => {
  const b = new Toasts(world.page, world.baseURL ?? '');
  await p.expectVisible(await b.toast(text));
}, { level: 'e2e' });

steps.step("Then I see no toast", async (world, _values) => {
  const b = new Toasts(world.page, world.baseURL ?? '');
  await p.expectCount(await b.toastsAll(), 0);
}, { level: 'e2e' });

steps.step("Then I see {n} toasts", async (world, { n }) => {
  const b = new Toasts(world.page, world.baseURL ?? '');
  await p.expectCount(await b.toastsAll(), Number(n));
}, { level: 'e2e' });

steps.step("When I press {name} on the toast", async (world, { name }) => {
  const b = new Toasts(world.page, world.baseURL ?? '');
  await p.click(await b.action(name));
}, { level: 'e2e' });

steps.step("Then the toaster is in the {state} state", async (world, { state }) => {
  const b = new Toasts(world.page, world.baseURL ?? '');
  await b.expectState(state);
}, { level: 'e2e' });
